export async function updateStatusesForNewAcademicYear(highSchoolFirstYearGeneration: number): Promise<{ error: string | null, message: string }> {
    try {
        await checkAdmin();
        if (!highSchoolFirstYearGeneration || highSchoolFirstYearGeneration <= 0) {
            return { error: '有効な期数を指定してください。', message: '' };
        }

        const supabase = await createAdminClient();

        const highSchoolGenerations = [
            highSchoolFirstYearGeneration,      // 1st year
            highSchoolFirstYearGeneration - 1,  // 2nd year
            highSchoolFirstYearGeneration - 2   // 3rd year
        ];
        const juniorHighSchoolGenerations = [
            highSchoolFirstYearGeneration + 1,  // 3rd year
            highSchoolFirstYearGeneration + 2,  // 2nd year
            highSchoolFirstYearGeneration + 3   // 1st year
        ];

        const allStudentGenerations = [...highSchoolGenerations, ...juniorHighSchoolGenerations];

        console.log('[年度更新] 高校生の期:', highSchoolGenerations);
        console.log('[年度更新] 中学生の期:', juniorHighSchoolGenerations);
        console.log('[年度更新] 在籍中の期（全）:', allStudentGenerations);

        // Get count before update for better message
        const { count: totalMembers, error: countError } = await supabase
            .from('members')
            .select('*', { count: 'exact', head: true })
            .is('deleted_at', null);

        if (countError) throw new Error(`メンバー数の取得に失敗: ${countError.message}`);


        // Update High School Students
        const { error: hsError, data: hsData } = await supabase
            .from('members')
            .update({ status: 1 }) // 1: High School
            .in('generation', highSchoolGenerations)
            .is('deleted_at', null)
            .select();
        if (hsError) throw new Error(`高校生の更新に失敗: ${hsError.message}`);
        console.log(`[年度更新] 高校生に更新: ${hsData?.length || 0}人`);

        // Update Junior High School Students
        const { error: jhsError, data: jhsData } = await supabase
            .from('members')
            .update({ status: 0 }) // 0: Junior High
            .in('generation', juniorHighSchoolGenerations)
            .is('deleted_at', null)
            .select();
        if (jhsError) throw new Error(`中学生の更新に失敗: ${jhsError.message}`);
        console.log(`[年度更新] 中学生に更新: ${jhsData?.length || 0}人`);

        // Update OB/OG (期が在籍中リストに含まれないメンバー)
        const { error: obError, data: obData } = await supabase
            .from('members')
            .update({ status: 2 }) // 2: OB/OG
            .not('generation', 'in', `(${allStudentGenerations.join(',')})`)
            .is('deleted_at', null)
            .select();
        if (obError) {
            console.error('[年度更新] OB/OG更新エラー:', obError);
            throw new Error(`OB/OGの更新に失敗: ${obError.message}`);
        }
        console.log(`[年度更新] OB/OGに更新: ${obData?.length || 0}人`, obData);

        // Re-sync all members' roles
        await syncAllDiscordRoles();

        revalidatePath('/dashboard/admin/members');

        return { error: null, message: `全${totalMembers || 0}人のメンバーのステータスを更新し、ロールの同期を開始しました。` };

    } catch (e: any) {
        console.error("Failed to update for new academic year:", e);
        return { error: e.message, message: '' };
    }
}


